def _generated_pairs(root):
    pairs = []
    for path in Path(root).rglob("*.py"):
        if any(part in {".git", ".venv", "__pycache__"} for part in path.parts): continue
        owner = generated_owner(path)
        if owner is not None: pairs.append((path, owner))
    return pairs

